    [11684]={name="Ironfoe",sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan in Blackrock Depths.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay.",proc="Chance on hit: Grants 2 extra attacks on your next swing."},
