    [19823]={name="Zandalar Vindicator's Belt",sourceType="quest_reward",instructions="Reward from the quest “Paragons of Power: The Vindicator's Belt”. In Zul'Gurub.",zone="Zul'Gurub",questName="Paragons of Power: The Vindicator's Belt",lore="Wreak havoc on the minions of evil. Zul'Gurub must taste Zandalar vengeance."},
