    [22418]={name="Dreadnaught Helmet",sourceType="quest_reward",instructions="Reward from the quest “Dreadnaught Helmet”. In Naxxramas.",zone="Naxxramas",questName="Dreadnaught Helmet",lore="During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."},
